var wrap = root.querySelector(".dd7-chip-set-chips");
var label = root.querySelector(".dd7-chip-set-n");
var reset = root.querySelector(".dd7-chip-set-reset");
var counts = [214, 96, 41];
function live(){ return chips.filter(function(c){ return !c.classList.contains("dd7-chip-set-chip-out"); }); }
function sync(){
  var n = live().length;
  label.textContent = n === 0 ? "No filters · 12,480 events" : (n + (n === 1 ? " filter · " : " filters · ") + counts[3 - n] + " events");
  root.classList.toggle("dd7-chip-set-clean", n === 0);
  reset.disabled = n === chips.length;
}
function remove(chip){
  chip.style.maxWidth = chip.offsetWidth + "px";
  void chip.offsetWidth;
  chip.classList.add("dd7-chip-set-chip-out");
  chip.style.maxWidth = "0px";
  chip.style.marginRight = "0px";
  chip.style.paddingLeft = "0px";
  chip.style.paddingRight = "0px";
  window.setTimeout(function(){ if (chip.classList.contains("dd7-chip-set-chip-out")) chip.classList.add("dd7-chip-set-chip-gone"); }, 360);
  sync();
}
