  var x = e.target.closest && e.target.closest(".dd7-chip-set-x");
  if (!x) return;
  var chip = x.closest(".dd7-chip-set-chip");
  var order = live();
  var i = order.indexOf(chip);
  remove(chip);
  var nxt = order[i + 1] || order[i - 1];
  if (nxt) nxt.querySelector(".dd7-chip-set-x").focus();
  else reset.focus();
});
reset.addEventListener("click", function(){
  chips.forEach(function(chip, i){
    if (!chip.classList.contains("dd7-chip-set-chip-out")) return;
    chip.classList.remove("dd7-chip-set-chip-gone", "dd7-chip-set-chip-out", "dd7-chip-set-chip-in");
