var copyBtn = root.querySelector(".dd7-spec-list-copy");
var reveal = root.querySelector(".dd7-spec-list-reveal");
var timer = null;
function fallback(text){
  var ta = window.document.createElement("textarea");
  ta.value = text;
  ta.setAttribute("readonly", "readonly");
  ta.style.cssText = "position:absolute;left:-9999px;top:0;opacity:0";
  root.appendChild(ta);
  ta.select();
  try { window.document.execCommand("copy"); } catch (err) {}
  root.removeChild(ta);
  copyBtn.focus();
}
copyBtn.addEventListener("click", function(){
  var text = copyBtn.getAttribute("data-copy");
  if (window.navigator.clipboard && window.navigator.clipboard.writeText) {
    window.navigator.clipboard.writeText(text).catch(function(){ fallback(text); });
  } else { fallback(text); }
  copyBtn.classList.add("dd7-spec-list-copy-done");
  window.clearTimeout(timer);
  timer = window.setTimeout(function(){ copyBtn.classList.remove("dd7-spec-list-copy-done"); }, 1500);
});
reveal.addEventListener("click", function(){
  var on = reveal.getAttribute("aria-pressed") !== "true";
  reveal.setAttribute("aria-pressed", on ? "true" : "false");
  reveal.setAttribute("aria-label", on ? "Hide connection secret" : "Reveal connection secret");
});

