var opts = Array.prototype.slice.call(root.querySelectorAll(".dd7-compare-table-opt"));
var tbl = root.querySelector(".dd7-compare-table-tbl");
function setMode(mode, focus){
  var annual = mode === "a";
  root.classList.toggle("dd7-compare-table-annual", annual);
  opts.forEach(function(o){
    var on = o.getAttribute("data-mode") === mode;
    o.classList.toggle("dd7-compare-table-opt-on", on);
    o.setAttribute("aria-checked", on ? "true" : "false");
    o.tabIndex = on ? 0 : -1;
    if (on && focus) o.focus();
  });
  Array.prototype.slice.call(root.querySelectorAll(".dd7-compare-table-rollin")).forEach(function(r){
    var kids = r.children;
    if (kids[0]) kids[0].setAttribute("aria-hidden", annual ? "true" : "false");
    if (kids[1]) kids[1].setAttribute("aria-hidden", annual ? "false" : "true");
  });
}
opts.forEach(function(o){
  o.addEventListener("click", function(){ setMode(o.getAttribute("data-mode"), false); });
  o.addEventListener("keydown", function(e){
    var i = opts.indexOf(o);
    if (e.key === "ArrowRight" || e.key === "ArrowDown") { setMode(opts[(i + 1) % opts.length].getAttribute("data-mode"), true); }
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") { setMode(opts[(i + opts.length - 1) % opts.length].getAttribute("data-mode"), true); }
    else if (e.key === "Home") { setMode(opts[0].getAttribute("data-mode"), true); }
    else if (e.key === "End") { setMode(opts[opts.length - 1].getAttribute("data-mode"), true); }
    else { return; }
    e.preventDefault();
  });
});
function hot(col){
  Array.prototype.slice.call(root.querySelectorAll(".dd7-compare-table-c")).forEach(function(c){
    c.classList.toggle("dd7-compare-table-hot", col !== null && c.getAttribute("data-col") === col);
  });
}
tbl.addEventListener("pointerover", function(e){
  var cell = e.target.closest && e.target.closest(".dd7-compare-table-c");
  hot(cell ? cell.getAttribute("data-col") : null);
});
tbl.addEventListener("pointerleave", function(){ hot(null); });
setMode("m", false);
